                        model.set_requires_gradient_sync(is_last_microbatch)
                    else:
                        for mlp in model[:num_mlps_to_disable_reduce_scatter]:
                            mlp.set_requires_gradient_sync(
                                is_last_microbatch, recurse=False
                            )
