    def __init__(self):
        self.inputs = []
        self.outputs = []
        self.constraints = []

    def add_int(self, symbol):
        self.inputs.append(symbol)
        self.constraints.append(symbol > 0)

    def add_input(self, constraint):
        self.constraints.append(constraint)

    def add_output(self, constraint):
        self.outputs.append(constraint)

    def validate(self):
        model = None
        failed_inputs = None
        if not self.constraints or not self.outputs:
            return {"success": False, "model": model, "failed_inputs": failed_inputs}

        # Create Z3 model.
        z3_model = z3.Solver()
        for constraint in self.constraints:
            z3_model.add(constraint)

        # Check if there are any solutions.
        if not z3_model.check():
            return {"success": False, "model": model, "failed_inputs": failed_inputs}

        # Get the model.
        model = z3_model.model()

