def _create_differentiable(inps, level=None):
    def create_differentiable(x):
        # This function is used to create differentiable functions.
        # It takes an input and returns a function that can be differentiated.
        # The level parameter is used to control the level of differentiation.
        # If level is None, the function will be differentiated to the first order.
        # If level is 1, the function will be differentiated to the second order, and so on.
        # The function will raise a ValueError if the level is not an integer.
        if not isinstance(level, int):
            raise ValueError("The level must be an integer.")
        if level < 0:
            raise ValueError("The level must be a non-negative integer.")

        # Create a differentiable function using the input x.
        # The function will be differentiated using the specified level.
        # The result will be a function that can be differentiated to the specified level.
        return lambda y: (y - x) * (y - x).sum() if level == 0 else (y - x).sum()

