    def test_jit_save(self):
        def fn():
            class Foo(torch.nn.Module):
                def __init__(self):
                    pass

                def forward(self, x):
                    return x + 1

            # Save the model
            model = Foo()
            jit_model = torch.jit.script(model)
            jit_model.save("test_jit_save.pt")

            # Load the model
            loaded_model = torch.jit.load("test_jit_save.pt")
            self.assertEqual(loaded_model(x=torch.rand(1)), x + 1)

    def test_no_recompile_inner_function(self):
        def forward(inp):
            def g(y):
                return inp + y

            print("graph break")
            return g(torch.rand([1]))

        cnts = torch._dynamo.testing.CompileCounter()
        opt_fn = torch._dynamo.optimize(cnts)(forward)

        input = torch.rand([2])
        _ = opt_fn(input)
        _ = opt_fn(input)
        _ = opt_fn(input)
        # Should not have recompiled
        self.assertEqual(cnts.frame_count, 1)

    def test_no_recompile_inner_lambda(self):
        def forward(inp):
            g = lambda y: inp + y
            print("graph break")
