class Barrier:
    def __init__(self, num_threads):
        self.num_threads = num_threads
        self.waiting = 0
        self.checkin_mutex  = thread.allocate_lock()

        # Added to handle the case where the barrier is not fully checked in
        self.checkin_condition = thread.Condition(self.checkin_mutex)

    def wait(self):
        with self.checkin_mutex:
            self.waiting += 1
            if self.waiting == self.num_threads:
                self.checkin_condition.notify_all()
            else:
                self.checkin_condition.wait()

    def signal(self):
        with self.checkin_mutex:
            self.waiting -= 1
            if self.waiting == 0:
                self.checkin_condition.notify_all()
