import json

def scanstring(data, idx, endchar, strict):
    if idx >= len(data):
        raise ValueError("Unexpected end of input")
    if data[idx] == endchar:
        return (data[idx:idx+1], idx+1)
    elif strict and not (data[idx] == '"' or data[idx] == "'"):
        raise ValueError("Unexpected character")
    else:
        return (data[idx:], idx)

