# Iterate over grouping intervals
def _grouping_intervals(grouping):
    last_interval = None
    for interval in grouping:
        # if grouping is -1, we are done
        if interval == CHAR_MAX:
            return
        # 0: re-use last group ad infinitum
        if interval == 0:
            if last_interval is None:
                raise ValueError("invalid grouping")
            while True:
                yield last_interval
        yield interval
        last_interval = interval

#perform the grouping from right to left
def _group(s, monetary=False):
    conv = localeconv()
    thousands_sep = conv[monetary and 'mon_thousands_sep' or 'thousands_sep']
    grouping = conv[monetary and 'mon_grouping' or 'grouping']
    if not grouping:
        return s
    # Split the string into groups
    groups = []
    current_group = []
    for char in s:
        if char == thousands_sep:
            groups.append(''.join(current_group))
            current_group = []
        else:
            current_group.append(char)
    if current_group:
        groups.append(''.join(current_group))
    # Reverse the groups to group from right to left
    groups.reverse()
    # Join the groups back together with thousands separators
    result = ''
    for group in groups:
        if group:
            result += group
            if grouping and len(result) > grouping[0]:
                result += thousands_sep
    return result

