    the underlying OS socket in an SSL context when necessary, and
    provides read and write methods over that channel."""

    def __init__(self, sock=None, keyfile=None, certfile=None,
                cert_reqs=CERT_NONE, ssl_version=PROTOCOL_TLSv1_2,
                ca_certs=None, do_handshake=True, suppress_ragged_eofs=False):
        super().__init__(sock)
        self._sslobj = None
        self._sslobj = ssl.wrap_socket(
            self, keyfile=keyfile, certfile=certfile,
            cert_reqs=cert_reqs, ssl_version=ssl_version,
            ca_certs=ca_certs, do_handshake=do_handshake,
            suppress_ragged_eofs=suppress_ragged_eofs)
        self._sslobj.owner = self

    @property
    def context(self):
        """The SSLContext that is currently in use."""
        return self._sslobj.context

    @context.setter
    def context(self, ctx):
        self._sslobj.context = ctx

    @property
    def server_side(self):
        """Whether this is a server-side socket."""
        return self._sslobj.server_side

